// Zweck: Video-Text aus der Supadata-Antwort holen und pruefen (mode native liefert bei vorhandenen Untertiteln direkt Text).
const r = $input.first().json;
const body = r.body || {};
let text = typeof body.content === 'string' ? body.content : (Array.isArray(body.content) ? body.content.map(t => t.text || '').join(' ') : '');
text = text.split(String.fromCharCode(10)).join(' ').replace(/ {2,}/g, ' ').trim();
// Warum kein Abbruch: 202 mit jobId (Auftrag statt Text), 206 (keine Untertitel) und zu kurzer Text laufen in den Ausweichweg F2.
let grund = '';
if (r.statusCode === 202 || body.jobId) grund = 'Supadata lieferte einen Auftrag (202) statt Text';
else if (r.statusCode === 206) grund = 'keine Untertitel vorhanden (206)';
else if (text.length < 500) grund = 'Video-Text zu kurz oder leer (' + text.length + ' Zeichen)';
return [{ json: { video_text: grund ? '' : text, video_text_zeichen: text.length, sprache: body.lang || null, f2_grund: grund, status_code: r.statusCode } }];

// Zweck: Paket der KI pruefen und in Form bringen (Folienzahl, Laengen, Hashtags, Kennzeichnung).
const ein = $input.first().json;
const p = ein.output || (typeof ein.text === 'string' ? JSON.parse(ein.text) : ein.text) || {};
const basis = $('Quelltext vereinheitlichen [Edit Fields]').first().json;
const cfg = $('Konfiguration und Startzeit [Edit Fields]').first().json;
const kunde = basis.kunde || {};
// Warum: F3, hat die Chain auf das Ersatzmodell umgeschaltet, steht das im Post und im Protokoll.
let ersatz = false;
try { ersatz = $('Ersatzmodell NVIDIA [NVIDIA Nemotron Chat Model]').isExecuted === true; } catch (e) { ersatz = false; }
// Warum aus dem Kostenknoten (v03): Tokens und Kosten erfasst der eigene Knoten direkt hinter dem HTTP-Aufruf, hier werden sie nur uebernommen.
const kost = $('Tokens und Kosten erfassen [Code]').first().json;
const vermerk = kost.kosten_vermerk ? [kost.kosten_vermerk] : [];
const tok = { token_prompt: kost.token_prompt, token_antwort: kost.token_antwort, token_gesamt: kost.token_gesamt, kosten_usd: kost.kosten_usd, token_quelle: kost.token_quelle };
// Warum nur ein Vermerk bei NVIDIA: der Ersatzweg laeuft durch dieselbe Kostenerfassung; NVIDIA Free Endpoint kostet 0, seine Tokens stehen nur im Modellknoten und sind im Code nicht lesbar.
if (ersatz) { vermerk.push('NVIDIA-Tokens nicht lesbar' + (kost.usage_da ? ', Token-Spalten nur OpenRouter' : '')); tok.token_quelle += ', nvidia ohne Tokenangabe'; }
const kuerze = (s, n) => { s = String(s || '').trim(); return s.length > n ? s.slice(0, n - 1).trimEnd() + '…' : s; };
let folien = (Array.isArray(p.folien) ? p.folien : []).filter(f => f && (f.ueberschrift || f.text));
// Warum: G9 verlangt 5 bis 8 Folien. Zu viele werden gekuerzt (die Abschlussfolie bleibt), zu wenige sind ein Fehler.
if (folien.length > 8) folien = folien.slice(0, 7).concat([folien[folien.length - 1]]);
// Warum Testschalter: 'pruefen' kuerzt hier auf 4 Folien, damit der Fehlerausgang dieses Knotens nachweisbar ist, Standard 'aus'.
if (cfg.test_folien_kuerzen === 'pruefen') folien = folien.slice(0, 4);
if (folien.length < 5) throw new Error('Paket hat nur ' + folien.length + ' Folien, verlangt sind 5 bis 8.');
folien = folien.map((f, i) => ({
  nr: i + 1,
  typ: i === 0 ? 'titel' : (i === folien.length - 1 ? 'abschluss' : 'inhalt'),
  ueberschrift: kuerze(f.ueberschrift, 70),
  text: kuerze(f.text, 260),
  cta: ''
}));
// Warum: die letzte Folie traegt immer die Handlungsaufforderung aus dem Kundenprofil, nicht die Formulierung des Modells.
folien[folien.length - 1].cta = kunde.cta_text || '';
// Warum: Hashtags ohne Leer- und Sonderzeichen, feste Marken-Hashtags zuerst, keine Doppelten.
const normTag = t => '#' + String(t || '').replace(/^#+/, '').replace(/[^A-Za-z0-9ÄÖÜäöüß_]/g, '');
// Warum (Paket 3, Hashtags doppelt): das Modell setzt Hashtags trotz Vorgabe teils auch in die Bildunterschrift. Sie werden dort herausgezogen und mit dem Feld hashtags zusammengefuehrt, damit jeder Tag nur einmal erscheint.
const capRoh = String(p.caption_instagram || '');
const tagMuster = /#(?=[\p{N}_]*\p{L})[\p{L}\p{N}_]+/gu;
const ausCaption = capRoh.match(tagMuster) || [];
const captionOhne = capRoh.replace(tagMuster, '').replace(/[ \t]+\n/g, '\n').replace(/\n{3,}/g, '\n\n').replace(/[ \t]{2,}/g, ' ').trim();
// Warum Map mit toLowerCase: #KI und #ki sind derselbe Tag, die erste Schreibweise gewinnt, feste Marken-Hashtags stehen zuerst.
const tagMap = new Map();
for (const t of (kunde.hashtags_fest || []).concat(p.hashtags || [], ausCaption).map(normTag)) { if (t.length > 1 && !tagMap.has(t.toLowerCase())) tagMap.set(t.toLowerCase(), t); }
const tags = Array.from(tagMap.values()).slice(0, 15);
// Warum (10.10.2026): photo_query und process_steps gehen an Foto suchen und an die Ablauf-Folie. Bereinigt, damit Render-Liste bauen nicht an Laengen scheitert; weniger als 3 Schritte heisst keine Ablauf-Folie.
const photoQuery = kuerze(String(p.photo_query || '').replace(/[#<>"]/g, ' ').replace(/\s+/g, ' '), 100);
const schritteRoh = (Array.isArray(p.process_steps) ? p.process_steps : []).map(s => String(s == null ? '' : s).trim()).filter(Boolean).slice(0, 5)
  .map(s => Array.from(s).length > 42 ? Array.from(s).slice(0, 41).join('').trimEnd() + '…' : s);
const processSteps = schritteRoh.length >= 3 ? schritteRoh : null;

return [{ json: {
  post_id: basis.post_id,
  kunde: kunde,
  quelle_art: basis.quelle_art,
  thema: basis.thema,
  folien: folien,
  anzahl_folien: folien.length,
  caption_instagram: kuerze(captionOhne, 2000),
  hashtags: tags,
  linkedin_post: kuerze(p.linkedin_post, 2900),
  // Warum 2.048: Obergrenze des Bildprompts bei FLUX schnell (Recherche-Vergleich, Punkt 7).
  bildprompt: kuerze(p.bildprompt, 2048),
  photo_query: photoQuery,
  process_steps: processSteps,
  kennzeichnung: 'KI-erstellt',
  ki_erstellt: true,
  ersatzmodell: ersatz,
  modell_genutzt: ersatz ? 'nvidia/nemotron-3-super-120b-a12b' : (ein.modell_antwort || cfg.modell_haupt),
  token_prompt: tok.token_prompt,
  token_antwort: tok.token_antwort,
  token_gesamt: tok.token_gesamt,
  kosten_usd: tok.kosten_usd,
  token_quelle: tok.token_quelle,
  kosten_vermerk: vermerk.join('; ')
} }];

// Zweck: je Folie und fuer das Einzelbild eine Datei index.html im Kundenbranding bauen, Gotenberg macht daraus PNG 1080 x 1350.
const paket = $('Branding-Variante wählen [Code]').first().json;
const k = paket.kunde || {};
const B = 1080, H = 1350;
// Warum Escaping: Texte stammen aus Quelle und Modell, sie duerfen kein HTML in die Folie schmuggeln.
const esc = s => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&#39;');
const hex = (v, d) => (/^#[0-9a-fA-F]{6}$/.test(v || '') ? v : d);
const c = { p: hex(k.farbe_primaer, '#15774E'), s: hex(k.farbe_sekundaer, '#515F56'), a: hex(k.farbe_akzent, '#22A26F'), bg: hex(k.farbe_hintergrund, '#F4FBF7'), t: hex(k.farbe_text, '#111C16') };
// Warum keine Webschriften: keine externen Adressen im HTML. Der Name aus dem Profil greift, wenn die Schrift im Render-Dienst liegt, sonst die Systemschrift.
const sauber = n => String(n || '').replace(/[^A-Za-z0-9 ÄÖÜäöüß-]/g, '');
// Warum einfache Anfuehrungszeichen: die Schriftliste steht auch in style-Attributen, doppelte wuerden das Attribut beenden.
const fTitel = "'" + sauber(k.schrift_titel) + "', 'DejaVu Sans', 'Liberation Sans', Arial, sans-serif";
const fText = "'" + sauber(k.schrift_text) + "', 'DejaVu Sans', 'Liberation Sans', Arial, sans-serif";

// Logo als Base64 einbetten (kommt als Binaerdatei aus Schritt Logo laden).
const ein = $input.first();
let logo = '';
if (ein.binary && ein.binary.logo) {
  const buf = await this.helpers.getBinaryDataBuffer(0, 'logo');
  logo = 'data:' + (ein.binary.logo.mimeType || 'image/png') + ';base64,' + buf.toString('base64');
}

// FLUX-Bild nehmen, wenn Schritt Einzelbild erzeugen ein Bild geliefert hat, sonst Fallback F4 (Farbverlauf plus Logo).
let bild = '', bildQuelle = 'farbverlauf_fallback', bildHinweis = '';
try {
  const r = $('Einzelbild erzeugen [HTTP Request]').first().json;
  const b64 = r && r.result && r.result.image;
  if (b64) { bild = 'data:' + (b64.startsWith('iVBOR') ? 'image/png' : 'image/jpeg') + ';base64,' + b64; bildQuelle = 'flux'; }
  else bildHinweis = 'F4: FLUX lieferte kein Bild, Einzelbild als Farbverlauf';
} catch (e) {
  bildHinweis = 'F4: Konto-ID fehlt, FLUX nicht aufgerufen, Einzelbild als Farbverlauf';
}

// Ein erfolgreich heruntergeladenes Foto hat Vorrang. Nicht ausgefuehrte Wege sind erlaubt.
let fotoCredit = null;
if ($('Foto einbetten [Code]').isExecuted) {
  const foto = $('Foto einbetten [Code]').first().json;
  if (foto.foto_data_uri) { bild = foto.foto_data_uri; bildQuelle = 'pixabay'; bildHinweis = ''; fotoCredit = foto.foto_credit; }
}
if ($('Foto auswerten [Code]').isExecuted && bildQuelle !== 'pixabay') {
  bildHinweis = [$('Foto auswerten [Code]').first().json.foto_hinweis, bildHinweis].filter(Boolean).join('; ');
}
if ($('Bild-Fallback vorbereiten [Code]').isExecuted) {
  bildHinweis = [$('Bild-Fallback vorbereiten [Code]').first().json.foto_hinweis, bildHinweis].filter(Boolean).join('; ');
}
if (paket.branding_pack.logo.modus === 'wortmarke') {
  // Neutraler Platzhalter als selbst erzeugtes SVG, das geladene Kundenlogo wird nicht genutzt.
  const wort = esc(String(paket.branding_pack.logo.text || 'TESTMARKE').slice(0, 24));
  logo = 'data:image/svg+xml;base64,' + Buffer.from('<svg xmlns="http://www.w3.org/2000/svg" width="300" height="300"><rect width="300" height="300" fill="' + c.bg + '"/><text x="150" y="158" text-anchor="middle" font-family="DejaVu Sans,Arial" font-size="22" fill="' + c.t + '">' + wort + '</text></svg>', 'utf8').toString('base64');
}

const folien = (paket.folien || []).map(f => ({...f}));
const schritte = paket.process_steps;
if (schritte != null) {
  if (!Array.isArray(schritte) || schritte.length < 3 || schritte.length > 5 || schritte.some(s => typeof s !== 'string' || !s.trim() || Array.from(s).length > 42)) {
    throw new Error('Ablauf-Folie verlangt 3 bis 5 nichtleere Schritte mit hoechstens 42 Zeichen.');
  }
  const ablauf = {typ: 'ablauf', ueberschrift: 'So läuft es ab', schritte};
  // Abschlussfolie bleibt letzte Folie. Bei 8 Folien wird die vorletzte Inhaltsfolie ersetzt.
  if (folien.length >= 8) folien.splice(folien.length - 2, 1, ablauf);
  else folien.splice(Math.max(0, folien.length - 1), 0, ablauf);
}
if (folien.length < 5 || folien.length > 8) throw new Error('Render-Liste verlangt 5 bis 8 Folien.');
const n = folien.length;
const W = n * B;
// Durchlaufendes Design: eine breite SVG-Flaeche ueber alle Folien, jede Folie zeigt ihren Ausschnitt (Versatz -i * 1080).
let welle = 'M0 ' + (H - 300);
let linie = 'M0 ' + (H - 400);
for (let x = 0; x <= W; x += 30) {
  welle += ' L' + x + ' ' + (H - 300 + Math.round(Math.sin(x / 520) * 70));
  linie += ' L' + x + ' ' + (H - 400 + Math.round(Math.sin(x / 520 + 1.3) * 80));
}
welle += ' L' + W + ' ' + H + ' L0 ' + H + ' Z';
let kreise = '';
for (let i = 0; i < n; i++) {
  const cx = i * B + (i % 2 ? 140 : 940), cy = i % 2 ? 250 : 320;
  kreise += '<circle cx="' + cx + '" cy="' + cy + '" r="220" fill="none" stroke="' + c.a + '" stroke-opacity="0.16" stroke-width="46"/>';
}
const flaeche = '<svg xmlns="http://www.w3.org/2000/svg" width="' + W + '" height="' + H + '" viewBox="0 0 ' + W + ' ' + H + '">' + kreise
  + '<path d="' + welle + '" fill="' + c.p + '"/>'
  + '<path d="' + linie + '" fill="none" stroke="' + c.a + '" stroke-width="14" stroke-linecap="round" stroke-linejoin="round"/></svg>';

const css = '*{margin:0;padding:0;box-sizing:border-box}'
  + 'html,body{width:1080px;height:1350px;overflow:hidden;background:' + c.bg + ';color:' + c.t + ';font-family:' + fText + '}'
  + '.buehne{position:relative;width:1080px;height:1350px;overflow:hidden}'
  + '.flaeche{position:absolute;top:0}'
  + '.kopf{position:absolute;top:72px;left:96px;right:96px;display:flex;align-items:center;gap:20px;font-family:' + fTitel + ';font-weight:600;font-size:30px;letter-spacing:0.02em}'
  + '.kopf img{width:64px;height:64px;object-fit:contain}'
  + '.zaehler{margin-left:auto;font-size:28px;color:' + c.s + ';font-variant-numeric:tabular-nums}'
  + '.inhalt{position:absolute;left:96px;right:96px;top:220px}'
  + '.nr{font-family:' + fTitel + ';font-size:120px;font-weight:800;line-height:1;color:' + c.a + '}'
  + 'h1{font-family:' + fTitel + ';font-size:86px;line-height:1.08;font-weight:800;letter-spacing:-0.01em;margin-top:40px}'
  + 'h2{font-family:' + fTitel + ';font-size:62px;line-height:1.12;font-weight:800;margin-top:24px}'
  + 'p{font-size:38px;line-height:1.4;margin-top:32px;max-width:880px}'
  + '.marke{display:inline-block;margin-top:44px;padding:14px 28px;border:4px solid ' + c.p + ';border-radius:999px;font-size:30px;font-weight:600;color:' + c.p + '}'
  + '.cta{display:inline-block;margin-top:44px;padding:24px 38px;border-radius:24px;background:' + c.p + ';color:' + c.bg + ';font-family:' + fTitel + ';font-size:38px;font-weight:700}'
  + '.ctazeile{display:flex;align-items:center;flex-wrap:wrap;gap:36px;margin-top:44px}'
  + '.ctazeile .cta{margin-top:0}'
  + '.grosslogo{width:150px;height:150px;object-fit:contain}'
  + '.fuss{position:absolute;left:96px;right:96px;bottom:56px;display:flex;justify-content:space-between;font-size:24px;color:' + c.bg + '}';

const zwei = z => String(z).padStart(2, '0');
const kennung = esc(paket.kennzeichnung || 'KI-erstellt');
const kopf = i => '<div class="kopf">' + (logo ? '<img src="' + logo + '" alt="">' : '') + '<span>' + esc(k.name) + '</span><span class="zaehler">' + zwei(i + 1) + ' / ' + zwei(n) + '</span></div>';
const fuss = '<div class="fuss"><span>' + kennung + '</span><span>' + esc(k.name) + '</span></div>';
const seite = koerper => '<!doctype html><html lang="de"><head><meta charset="utf-8"><style>' + css + '</style></head><body><div class="buehne">' + koerper + '</div></body></html>';

const items = [];
const layouts = paket.branding_varianten;
const layoutCss = v => {
  if (v.stil === 'thema') return '.nr{display:none}.inhalt{top:300px}.marke{border-radius:0}.flaeche{opacity:.35}';
  if (v.stil === 'ablauf') return '.nr{font-size:72px}.marke{border-radius:12px}.inhalt{top:200px}';
  return '.kopf{border-bottom:3px solid ' + c.a + ';padding-bottom:24px}.marke{border-radius:999px}';
};
const seitentyp = (koerper, v) => seite(koerper).replace('</style>', layoutCss(v) + '</style>');
const basisJson = { post_id: paket.post_id, kunde_kuerzel: k.kuerzel, bild_quelle: bildQuelle, bild_hinweis: bildHinweis };
for (let i = 0; i < n; i++) {
  const f = folien[i];
  let mitte;
  if (f.typ === 'titel') {
    mitte = '<div class="inhalt"><h1>' + esc(f.ueberschrift) + '</h1><p>' + esc(f.text) + '</p><span class="marke">' + esc(k.name) + '</span></div>';
  } else if (f.typ === 'ablauf') {
    mitte = '<div class="inhalt" style="top:200px"><h2 style="font-size:56px;margin:0 0 28px">' + esc(f.ueberschrift) + '</h2>';
    f.schritte.forEach((s, index) => {
      mitte += '<div style="border:3px solid ' + c.p + ';background:' + c.bg + ';padding:18px 24px;font-size:34px;line-height:1.15;border-radius:12px">' + (index + 1) + '. ' + esc(s) + '</div>';
      if (index < f.schritte.length - 1) mitte += '<div style="height:36px;text-align:center;font-size:30px;line-height:36px;color:' + c.p + '">↓</div>';
    });
    mitte += '</div>';
  } else if (f.typ === 'abschluss') {
    // Warum eine Zeile mit Umbruch: Handlungsaufforderung und Logo duerfen sich bei langem Text nicht ueberdecken.
    mitte = '<div class="inhalt"><h2>' + esc(f.ueberschrift) + '</h2><p>' + esc(f.text) + '</p><div class="ctazeile">'
      + (f.cta ? '<div class="cta">' + esc(f.cta) + '</div>' : '')
      + (logo ? '<img class="grosslogo" src="' + logo + '" alt="">' : '') + '</div></div>';
  } else {
    mitte = '<div class="inhalt"><div class="nr">' + zwei(i) + '</div><h2>' + esc(f.ueberschrift) + '</h2><p>' + esc(f.text) + '</p></div>';
  }
  const html = seitentyp('<div class="flaeche" style="left:-' + (i * B) + 'px">' + flaeche + '</div>' + kopf(i) + mitte + fuss, layouts.instagram.karussell);
  const datei = 'folie-' + zwei(i + 1) + '.png';
  const bin = await this.helpers.prepareBinaryData(Buffer.from(html, 'utf8'), 'index.html', 'text/html');
  items.push({ json: Object.assign({ art: 'folie', plattform: 'instagram', format: 'karussell', branding_variante: layouts.instagram.karussell.id, nr: i + 1, datei, pfad: k.kuerzel + '/' + paket.post_id + '/' + datei, html_zeichen: html.length }, basisJson), binary: { index_html: bin }, pairedItem: { item: 0 } });
}

// Einzelbild: FLUX-Bild als Hintergrund mit Logo, oder Farbverlauf aus den Kundenfarben plus Logo und Titel (F4).
const titel = (folien[0] && folien[0].ueberschrift) || paket.thema || '';
let eb;
if (bild) {
  eb = '<div style="position:absolute;inset:0;background:url(' + bild + ') center/cover no-repeat"></div>'
    + '<div style="position:absolute;inset:0;background:linear-gradient(180deg,rgba(0,0,0,0) 55%,rgba(0,0,0,0.55) 100%)"></div>';
} else {
  eb = '<div style="position:absolute;inset:0;background:linear-gradient(160deg,' + c.p + ' 0%,' + c.p + ' 35%,' + c.a + ' 100%)"></div>'
    + '<svg style="position:absolute;inset:0" width="1080" height="1350"><circle cx="900" cy="260" r="260" fill="none" stroke="' + c.bg + '" stroke-opacity="0.18" stroke-width="56"/><circle cx="120" cy="1180" r="200" fill="none" stroke="' + c.bg + '" stroke-opacity="0.14" stroke-width="40"/></svg>'
    + '<div style="position:absolute;left:96px;right:96px;top:320px;font-family:' + fTitel + ';font-size:84px;font-weight:800;line-height:1.08;color:' + c.bg + '">' + esc(titel) + '</div>';
}
if (logo) {
  eb += '<div style="position:absolute;right:72px;bottom:72px;width:180px;height:180px;border-radius:50%;background:' + c.bg + ';display:flex;align-items:center;justify-content:center;box-shadow:0 12px 40px rgba(0,0,0,.25)"><img src="' + logo + '" style="width:124px;height:124px;object-fit:contain" alt=""></div>';
}
eb += '<div style="position:absolute;left:72px;bottom:84px;font-size:24px;color:' + c.bg + ';text-shadow:0 2px 8px rgba(0,0,0,.35)">' + kennung + '</div>';
const einzelLayout = layouts.linkedin.einzelpost;
if (einzelLayout.stil === 'thema' && bild) {
  eb += '<div style="position:absolute;left:72px;right:72px;top:180px;background:' + c.bg + ';color:' + c.t + ';padding:36px;font-size:64px;font-weight:800">' + esc(titel) + '</div>';
} else if (einzelLayout.stil === 'ablauf') {
  eb += '<div style="position:absolute;left:72px;right:72px;top:160px;background:' + c.bg + ';color:' + c.t + ';padding:32px;font-size:32px;line-height:1.3">' + esc(titel) + '<ol style="padding-left:48px;margin-top:24px">' + (schritte || []).map(s => '<li style="margin-bottom:20px">' + esc(s) + '</li>').join('') + '</ol></div>';
}
if (fotoCredit) eb += '<div style="position:absolute;left:72px;right:280px;bottom:130px;background:' + c.bg + ';color:' + c.t + ';padding:8px;font-size:18px">Foto: ' + esc(fotoCredit.fotograf) + ' / Pixabay</div>';
const ebHtml = seitentyp(eb, einzelLayout);
const ebBin = await this.helpers.prepareBinaryData(Buffer.from(ebHtml, 'utf8'), 'index.html', 'text/html');
items.push({ json: Object.assign({ art: 'einzelbild', plattform: 'linkedin', format: 'einzelpost', branding_variante: layouts.linkedin.einzelpost.id, foto_credit: fotoCredit, nr: 0, datei: 'einzelbild.png', pfad: k.kuerzel + '/' + paket.post_id + '/einzelbild.png', html_zeichen: ebHtml.length }, basisJson), binary: { index_html: ebBin }, pairedItem: { item: 0 } });
return items;

// Zweck: aus jedem Abbruch (E5, F6, F3, F5, F8) genau eine Protokollzeile mit Stelle fehlerweg bauen, nur Metadaten.
// Warum seit v05 nur Abbrueche: Ersatzwege (F1, F2, F3 Ersatzmodell, F4, F7) stehen in der Protokollzeile am Ende.
// Warum einmal fuer alle Elemente (v02): kommen mehrere Fehler-Elemente an (Bild hochladen je Bild), entsteht trotzdem nur eine Zeile.
const k = $('Konfiguration und Startzeit [Edit Fields]').first().json;
