// Warum all(i): Ausgang 0 ist das Ergebnis, Ausgang 1 der Fehlerausgang mit der Fehlermeldung.
const ausgang = (n, i) => { try { return $(n).all(i) || []; } catch (e) { return []; } };
const fehlerVon = n => { const it = ausgang(n, 1)[0]; const e = it && it.json && it.json.error; return e ? String(e.message || e).slice(0, 160) : ''; };
let post = null;
if (lief('Post anlegen [Supabase]')) post = $('Post anlegen [Supabase]').first().json.id || null;
// Warum diese Liste (v02): nach dem bezahlten Modellaufruf darf kein Abbruch mehr ohne Zeile enden; F8 = Abbruch nach dem Modellaufruf.
