else if (lief('Status fehler setzen [Supabase]')) text = 'F3: Hauptmodell und Ersatzmodell ohne gültiges Paket (' + (fehlerVon('Ersatzpaket schreiben [Basic LLM Chain]') || 'unbekannt') + ')';
else text = String(ein.fehler_text || 'Abbruch ohne Text');
// Warum: bricht der Lauf ab, laeuft die Protokollzeile am Ende nicht mehr, deshalb stehen fruehere Ersatzwege hier mit.
const ppOk = ausgang('Paket prüfen [Code]', 0);
const pp = ppOk.length ? ppOk[0].json : null;
const nvLief = ausgang('Ersatzpaket schreiben [Basic LLM Chain]', 0).length > 0 || ausgang('Ersatzpaket schreiben [Basic LLM Chain]', 1).length > 0;
const frueher = [];
if (lief('Quelle-Fallback F1 [Edit Fields]')) frueher.push('F1');
if (lief('Video-Fallback F2 [Edit Fields]')) frueher.push('F2');
if ((pp && pp.ersatzmodell) || (!pp && nvLief && !lief('Status fehler setzen [Supabase]'))) frueher.push('F3 Ersatzmodell');
const rl = ausgang('Render-Liste bauen [Code]', 0);
if (rl.length && rl[0].json.bild_quelle !== 'flux') frueher.push('F4');
const zeile = {
  workflow_name: k.workflow_name,
  execution_id: k.execution_id,
  ausfuehrung_modus: k.ausfuehrung_modus,
  stelle: 'fehlerweg',
  status: 'fehler',
  dauer_ms: Math.round(Date.now() - new Date(k.startTime).getTime()),
  modell: nvLief ? 'nvidia/nemotron-3-super-120b-a12b' : k.modell_haupt,
  kunde_kuerzel: k.kunde_kuerzel
};
// Warum ohne post_id bei E5 und F6: vor dem Anlegen des Posts gibt es keine UUID, ein leerer Wert waere fuer die Spalte ungueltig.
if (post) zeile.post_id = post;
// Warum: auch ein Abbruch nach einem bezahlten Modellaufruf traegt Tokens und Kosten, fehlende Kosten bleiben null mit Vermerk.
const vermerk = [];
if (pp) {
  zeile.modell = pp.modell_genutzt; zeile.token_prompt = pp.token_prompt; zeile.token_antwort = pp.token_antwort; zeile.token_gesamt = pp.token_gesamt; zeile.kosten_usd = pp.kosten_usd;
  if (pp.kosten_vermerk) vermerk.push(pp.kosten_vermerk);
} else if (lief('Tokens und Kosten erfassen [Code]')) {
  // Warum aus dem Kostenknoten (v03): er laeuft auf beiden Wegen (Antwort und Fehlerausgang), auch wenn danach beide Modelle scheitern.
  const kq = $('Tokens und Kosten erfassen [Code]').first().json;
  zeile.token_prompt = kq.token_prompt;
  zeile.token_antwort = kq.token_antwort;
  zeile.token_gesamt = kq.token_gesamt;
