  modell: p.modell_genutzt, kunde_kuerzel: (p.kunde || {}).kuerzel, post_id: p.post_id,
  fehler_text: hinweise.join('; ').slice(0, 300),
  // Warum: Tokens und Kosten aus Paket pruefen, Quelle steht dort in token_quelle.
  token_prompt: p.token_prompt, token_antwort: p.token_antwort, token_gesamt: p.token_gesamt, kosten_usd: p.kosten_usd
