// Zweck: Antwort von OpenRouter in das bisherige Paketformat bringen und gegen das Schema von K1 v05 pruefen. Tokens und Kosten erfasst seit v03 der Knoten davor.
const k = $input.first().json;
const cfg = $('Konfiguration und Startzeit [Edit Fields]').first().json;
// Warum Wurf ohne Antwort: Zeitlimit oder HTTP-Fehler, die Kostenerfassung hat den Vermerk schon; der Fehlerausgang fuehrt zum Ersatzmodell NVIDIA (F3).
if (!k.antwort_da) throw new Error('OpenRouter ohne Antwort (' + (k.openrouter_fehler || 'ohne Meldung') + ')');
const r = k.openrouter_antwort || {};
const wahl = (r.choices || [])[0] || {};
const inhalt = String((wahl.message || {}).content || '');
// Warum Codeblock entfernen: manche Modelle setzen das JSON trotz Vorgabe zwischen drei Backticks.
const roh = inhalt.replace(/^\s*```(?:json)?\s*/i, '').replace(/\s*```\s*$/, '');
let paket;
try { paket = JSON.parse(roh); } catch (e) { throw new Error('Antwort ist kein gültiges JSON (finish_reason ' + (wahl.finish_reason || 'unbekannt') + ')'); }
if (!paket || typeof paket !== 'object' || Array.isArray(paket)) throw new Error('Antwort ist kein JSON-Objekt');
// Warum Testschalter: (07.10.2026) laesst sich nur mit einem zu kurzen Paket nachweisen; 'lesen' kuerzt hier auf 4 Folien, Standard 'aus'.
if (cfg.test_folien_kuerzen === 'lesen' && Array.isArray(paket.folien)) paket.folien = paket.folien.slice(0, 4);
// Warum hier pruefen: dieselben Grenzen wie der Structured Output Parser in K1 v05, ein Verstoss geht ueber den Fehlerausgang zum Ersatzmodell (F3).
const pflicht = ['folien', 'caption_instagram', 'hashtags', 'linkedin_post', 'bildprompt'];
const fehlt = pflicht.filter(f => paket[f] === undefined);
if (fehlt.length) throw new Error('Paket ohne Pflichtfelder: ' + fehlt.join(', '));
const verstoss = [];
if (!Array.isArray(paket.folien)) verstoss.push('folien ist keine Liste');
else {
  // Warum 5 bis 8: minItems und maxItems im Parser-Schema von K1 v05 (G9).
  if (paket.folien.length < 5 || paket.folien.length > 8) verstoss.push(paket.folien.length + ' Folien statt 5 bis 8');
  paket.folien.forEach((f, i) => {
    if (!f || typeof f !== 'object') { verstoss.push('Folie ' + (i + 1) + ' ist kein Objekt'); return; }
    if (!['titel', 'inhalt', 'abschluss'].includes(f.typ)) verstoss.push('Folie ' + (i + 1) + ' mit unbekanntem typ');
    if (typeof f.ueberschrift !== 'string' || typeof f.text !== 'string') verstoss.push('Folie ' + (i + 1) + ' ohne Überschrift oder Text als Zeichenkette');
  });
  // Warum zusaetzlich: Paket pruefen verwirft leere Folien, danach duerfen es nicht weniger als 5 sein.
  const gefuellt = paket.folien.filter(f => f && (f.ueberschrift || f.text)).length;
  if (gefuellt < 5 && paket.folien.length >= 5) verstoss.push('nur ' + gefuellt + ' gefüllte Folien');
}
for (const f of ['caption_instagram', 'linkedin_post', 'bildprompt']) if (typeof paket[f] !== 'string') verstoss.push(f + ' ist keine Zeichenkette');
if (!Array.isArray(paket.hashtags) || paket.hashtags.some(t => typeof t !== 'string')) verstoss.push('hashtags ist keine Liste aus Zeichenketten');
if (verstoss.length) throw new Error('Paket verletzt das Schema: ' + verstoss.join('; '));
return [{ json: { output: paket, modell_antwort: k.modell_antwort } }];

// Zweck: Tokens und Kosten des OpenRouter-Aufrufs erfassen, als eigener sichtbarer Schritt direkt hinter dem HTTP-Knoten (W04T04 Punkt 3).
// Warum beide Ausgaenge hier ankommen: auch der Ersatzweg NVIDIA laeuft durch diese Kostenerfassung, damit ein Ausfall sichtbar null mit Vermerk schreibt, nie 0.
// Warum kein Wurf: der Knoten steht nach dem bezahlten Aufruf, ein Fehler hier darf die Antwort nicht verlieren; Probleme landen im Vermerk.
const zahl = v => (typeof v === 'number' && isFinite(v)) ? v : null;
const vermerk = [];
let r = {};
let antwortDa = false, usageDa = false;
let tok = { token_prompt: null, token_antwort: null, token_gesamt: null, kosten_usd: null };
let fehlerText = '';
try {
  r = ($input.first() || {}).json || {};
  // Warum choices als Kennzeichen der Antwort: nur eine echte Antwort von OpenRouter traegt choices, der Fehlerausgang traegt error.
  antwortDa = Array.isArray(r.choices);
  // Warum usage unabhaengig von choices: liefert OpenRouter usage ohne choices, sind die Kosten trotzdem angefallen und bekannt.
  const u = (r.usage && typeof r.usage === 'object') ? r.usage : null;
  usageDa = !!u;
  if (u) {
    // Warum usage.cost: OpenRouter liefert die Kosten in USD fertig mit, keine Preistabelle, die still veraltet.
    tok = { token_prompt: zahl(u.prompt_tokens), token_antwort: zahl(u.completion_tokens), token_gesamt: zahl(u.total_tokens), kosten_usd: zahl(u.cost) };
    // Warum kein 0: fehlt usage.cost, ist der Preis unbekannt, nicht kostenlos.
    if (tok.kosten_usd === null) vermerk.push('Kosten unbekannt: OpenRouter-Antwort ohne usage.cost');
    if (tok.token_gesamt === null) vermerk.push('Tokens unbekannt: OpenRouter-Antwort ohne usage');
  } else if (antwortDa) {
    vermerk.push('Kosten unbekannt: OpenRouter-Antwort ohne usage.cost');
    vermerk.push('Tokens unbekannt: OpenRouter-Antwort ohne usage');
  } else {
    // Warum unbekannt statt 0: ein Zeitlimit beweist nur, dass keine Antwort kam, nicht dass nichts abgerechnet wurde.
    vermerk.push('Kosten unbekannt: OpenRouter ohne Antwort (Zeitlimit oder Fehler), Abrechnung nicht messbar');
  }
  if (!antwortDa) {
    // Warum Zeichenkette zulassen: der HTTP-Knoten liefert den Fehler teils als Text, teils als Objekt mit Ursache.
    const e = r.error;
    const teile = typeof e === 'string' ? [e] : (e && typeof e === 'object') ? [e.message || e.description, e.cause && e.cause.message] : [];
    fehlerText = (teile.filter(Boolean).join(', ') || (usageDa ? 'Antwort ohne choices' : 'Fehlerausgang ohne Meldung')).slice(0, 160);
  }
} catch (e) {
  vermerk.push('Kostenerfassung fehlgeschlagen: ' + String(e.message || e).slice(0, 120));
}
return [{ json: {
  antwort_da: antwortDa,
  usage_da: usageDa,
  openrouter_antwort: antwortDa ? r : null,
  openrouter_fehler: fehlerText,
  modell_antwort: antwortDa ? (r.model || '') : '',
  token_prompt: tok.token_prompt,
  token_antwort: tok.token_antwort,
  token_gesamt: tok.token_gesamt,
  kosten_usd: tok.kosten_usd,
  token_quelle: usageDa ? 'openrouter usage' : 'ohne openrouter usage',
  kosten_vermerk: vermerk.join('; ')
} }];

// 1 Kunde und 1 Paket je Auftrag. photo_query und process_steps kommen seit 10.10.2026 bereinigt aus Paket pruefen.
const paket = $('Paket prüfen [Code]').first().json;
const row = $input.first().json;
if (!row || row.kuerzel !== paket.kunde?.kuerzel) throw new Error('Branding-Kunde fehlt oder passt nicht zum Auftrag.');
// Platzhalter aus dem eigenen Kundenprofil (Farben, Schriften, Logo), Entscheidung vom 10.10.2026. Greift nur, wenn branding_pack leer ist.
const pk = paket.kunde || {};
const farbe = (v, d) => (/^#[0-9a-fA-F]{6}$/.test(v || '') ? v : d);
const standard = {version: 1, status: 'platzhalter', markenname: pk.name || 'Kunde',
  logo: {modus: 'datei', pfad: pk.logo_url || '', text: pk.name || ''},
