  farben: {primaer: farbe(pk.farbe_primaer, '#15774E'), sekundaer: farbe(pk.farbe_sekundaer, '#515F56'), akzent: farbe(pk.farbe_akzent, '#22A26F'), hintergrund: farbe(pk.farbe_hintergrund, '#F4FBF7'), text: farbe(pk.farbe_text, '#111C16')},
  postformen: ['hybrid_personen', 'thema', 'ablauf'],
