let b = row.branding_pack;
if (typeof b === 'string') b = JSON.parse(b);
if (b == null) b = standard;
if (typeof b !== 'object' || Array.isArray(b)) throw new Error('branding_pack muss ein JSON-Objekt sein.');
b = {...standard, ...b, logo: {...standard.logo, ...b.logo}, schriften: {...standard.schriften, ...b.schriften}, farben: {...standard.farben, ...b.farben}};
const kunde = {...paket.kunde, name: b.markenname};
for (const [key, value] of Object.entries(b.farben)) {
  if (!/^#[0-9a-fA-F]{6}$/.test(value)) throw new Error('Ungueltige Branding-Farbe: ' + key);
  kunde['farbe_' + key] = value;
}
kunde.schrift_titel = b.schriften.titel;
kunde.schrift_text = b.schriften.text;
const varianten = {};
for (const plattform of ['instagram', 'linkedin']) {
  varianten[plattform] = {};
  for (const format of ['karussell', 'einzelpost']) {
    const liste = b.layouts?.[plattform]?.[format];
    if (!Array.isArray(liste) || liste.length < 3 || liste.length > 5) throw new Error('3 bis 5 Layouts verlangt: ' + plattform + '/' + format);
    const postform = paket.process_steps?.length ? 'ablauf' : (paket.postform || 'hybrid_personen');
    const variante = liste.find(v => v.postform === postform) || liste[0];
    if (!variante.id || !['hybrid_personen', 'thema', 'ablauf'].includes(variante.stil)) throw new Error('Layout-ID oder Stil ungueltig.');
    varianten[plattform][format] = variante;
  }
}
const cfg = $('Konfiguration und Startzeit [Edit Fields]').first().json;
const plattform = String(paket.plattform || cfg.plattform || 'instagram').toLowerCase();
const format = String(paket.format || cfg.format || 'karussell').toLowerCase();
if (!varianten[plattform]?.[format]) throw new Error('Unbekannte Plattform oder unbekanntes Format.');
return [{json: {...paket, kunde, branding_pack: b, branding_varianten: varianten,
