// Auth-, Timeout- und Leerantworten fuehren sichtbar zum vorhandenen FLUX-Weg.
// Warum Pixabay (10.10.2026): Pexels stellt keine neuen API-Schluessel mehr aus. Treffer stehen in body.hits, das Bild in largeImageURL (hoechstens 1280 px).
const basis = $('Branding-Variante wählen [Code]').first().json;
const r = $input.first().json;
const body = r.body || r;
const hits = Array.isArray(body.hits) ? body.hits : [];
// Warum der Suchbegriff geprueft wird: ohne q liefert Pixabay beliebte Bilder statt eines passenden Fotos.
const frage = String(basis.photo_query || '').trim();
// Warum Muster statt new URL: im Code-Knoten dieser Instanz verwarf new URL alle 5 echten Treffer (Hilfsaufruf 733). Das Muster laesst nur https://pixabay.com/ bzw. https://cdn.pixabay.com/ ohne Port und Zugangsdaten zu.
const safePhoto = s => typeof s === 'string' && /^https:\/\/(cdn\.)?pixabay\.com\/[^\s"'<>]*$/.test(s);
const safeLink = s => typeof s === 'string' && /^https:\/\/(www\.)?pixabay\.com\/[^\s"'<>]*$/.test(s);
const p = frage ? hits.find(h => safePhoto(h.largeImageURL) && safeLink(h.pageURL)) : null;
const status = Number(r.statusCode || 200);
const ok = !r.error && status >= 200 && status < 300 && !!p;
// Warum Herkunft mitgeben: Pixabay verlangt, dass die Quelle sichtbar ist; Render-Liste bauen schreibt sie aufs Bild.
const nutzerUrl = ok && safeLink(p.userURL) ? p.userURL : '';
return [{json: {...basis, foto_ok: ok, foto_url: ok ? p.largeImageURL : '',
  foto_credit: ok ? {fotograf: String(p.user || ''), fotograf_url: nutzerUrl, quelle: 'Pixabay', pixabay_url: p.pageURL, photo_id: p.id} : null,
  foto_hinweis: ok ? '' : (r.error ? 'Pixabay-Anfrage gescheitert, weiter mit FLUX.' : 'Pixabay ohne nutzbaren Treffer (Status ' + status + ', ' + hits.length + ' Treffer), weiter mit FLUX.')}, pairedItem: {item: 0}}];

// Binaere Speichermodi ueber den n8n-Helper lesen, kein direkter Zugriff auf binary.data.
const basis = $('Foto auswerten [Code]').first().json;
const item = $input.first();
if (!item.binary?.foto) throw new Error('Foto-Download hat keine Binaerdatei geliefert.');
const buffer = await this.helpers.getBinaryDataBuffer(0, 'foto');
const jpeg = buffer.length > 3 && buffer[0] === 255 && buffer[1] === 216 && buffer[2] === 255;
const png = buffer.length > 8 && buffer.subarray(0, 8).equals(Buffer.from([137,80,78,71,13,10,26,10]));
if ((!jpeg && !png) || buffer.length > 12 * 1024 * 1024) throw new Error('Foto ist kein JPEG/PNG oder groesser als 12 MiB.');
return [{json: {...basis, foto_data_uri: 'data:' + (png ? 'image/png' : 'image/jpeg') + ';base64,' + buffer.toString('base64')}, pairedItem: {item: 0}}];

// Fehlerausgaenge koennen den Prompt verlieren. Validierten Kontext gezielt wiederherstellen.
const basis = $('Branding-Variante wählen [Code]').first().json;
const fehler = $input.first().json;
return [{json: {...basis, foto_ok: false, foto_url: '', foto_data_uri: '', foto_credit: null,
  foto_hinweis: 'Pixabay-Fotopfad gescheitert, Kontext wiederhergestellt, weiter mit FLUX.',
  foto_fehler: String(fehler.error?.message || fehler.message || 'Foto konnte nicht verarbeitet werden.').slice(0, 240)}, pairedItem: {item: 0}}];
